from jsonb_to_recordset($json$[{"id":"che-pe-245","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Metalloids show a mixture of","options":["only ionic bonding","metallic and non-metallic properties","no electrical conductivity ever","f-block chemistry only"],"answer_index":1,"explanation":"Elements on the p-block staircase (B, Si, Ge, As, Sb, Te) are the usual metalloids.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"metallic-character","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-246","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"In the third period the most metallic element is","options":["chlorine","silicon","sodium","argon"],"answer_index":2,"explanation":"Na stands at the left of period 3 and has the lowest IE of that row.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"metallic-character","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-247","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"In the second period the most non-metallic element is","options":["lithium","carbon","fluorine","beryllium"],"answer_index":2,"explanation":"Fluorine has the highest electronegativity and a very high IE among the period-2 non-nobles.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"metallic-character","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-248","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The reducing power of alkali metals increases down the group, in parallel with","options":["ionisation enthalpy","metallic character","electronegativity","electron gain enthalpy becoming more negative"],"answer_index":1,"explanation":"The heavier alkali metal loses its ns¹ electron more easily and is therefore the stronger reductant.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"metallic-character","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-249","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Metallic character in the set Na, Mg, Al decreases from","options":["aluminium to sodium","sodium to aluminium","magnesium to sodium","aluminium to argon"],"answer_index":1,"explanation":"Across period 3 the atoms become smaller and harder to ionise, so metallic character falls Na > Mg > Al.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"metallic-character","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-250","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Among Li, Na and K, potassium is the most metallic because it has the","options":["smallest size and highest IE","largest size and the lowest ionisation enthalpy","highest electronegativity","closed 3p⁶ valence shell"],"answer_index":1,"explanation":"Down group 1, size rises and IE falls, so K loses its 4s electron most readily of the three.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"metallic-character","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-251","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Lithium shows a diagonal resemblance in several of its compounds to","options":["sodium","magnesium","potassium","fluorine"],"answer_index":1,"explanation":"Li and Mg have similar charge-to-radius ratios, so their oxides, fluorides and carbonates behave alike.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"metallic-character","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-252","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Silicon is classified as a metalloid, sitting on the diagonal staircase of the","options":["s-block","p-block","f-block","noble-gas column"],"answer_index":1,"explanation":"Si lies between the metal Al and the non-metal P and shows intermediate electrical and chemical behaviour.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"metallic-character","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-253","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Caesium is more metallic than lithium because the valence electron of Cs is","options":["closer to the nucleus and harder to lose","farther from the nucleus and more easily lost","a 2s electron","part of a filled p⁶ set"],"answer_index":1,"explanation":"The 6s electron of Cs is highly shielded, so Cs has a very low IE and extreme metallic character.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"metallic-character","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-254","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Aluminium is distinctly more metallic than boron, even though both head group 13, because Al is","options":["smaller and has a higher ionisation enthalpy","larger and has a much lower ionisation enthalpy","a noble gas","an f-block element"],"answer_index":1,"explanation":"Two trends reinforce: down the group size rises and IE falls, turning the head (B, a non-metal/metalloid) into a metal (Al).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"metallic-character","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-255","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The first element of a p-block or s-block group differs markedly from the","options":["noble gases only","heavier members of that group","isotopes of hydrogen","inner transition metals alone"],"answer_index":1,"explanation":"Li, Be, B, C, N, O and F are the classic anomalous first members.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"anomalous-first","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-256","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The anomalous behaviour of the first element is largely due to its","options":["large size and low electronegativity","small size and high electronegativity","empty 4f subshell","very low ionisation enthalpy"],"answer_index":1,"explanation":"A compact valence shell and high χ (and IE) set the head element apart from its congeners.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"anomalous-first","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
